"""Contract checks run only on GitHub Actions; generated bytes are NOT accuracy evidence."""
import json
from pathlib import Path
from tempfile import TemporaryDirectory
from external_corpus_gate import validate

def run():
    with TemporaryDirectory() as name:
        root = Path(name)
        for file, data in [("a.bin", b"hello"), ("b.bin", b"world")]:
            (root/file).write_bytes(data)
        def sample(path, split, source, doc):
            return {"path": path, "encoding": "ascii", "source_id": source,
                    "document_id": doc, "split": split, "license": "CC0-1.0",
                    "origin_url": "https://example.invalid/fixture",
                    "verification_method": "creator_attestation"}
        def check(rows, expected):
            f = root/"manifest.jsonl"
            f.write_text("\n".join(json.dumps(r) for r in rows)+"\n")
            outcome = validate(f, root)
            assert outcome["ok"] == expected, outcome
        good = [sample("a.bin", "train", "s1", "d1"), sample("b.bin", "confirmation", "s2", "d2")]
        check(good, True)
        check([good[0], {**good[1], "source_id": "s1"}], False)
        check([good[0], {**good[1], "document_id": "d1"}], False)
        check([good[0], {**good[1], "path": "a.bin"}], False)
        check([good[0]], False)
        check([good[0], {**good[1], "verification_method": "unknown"}], False)
        check([good[0], {**good[1], "path": "../escape.bin"}], False)
        check([good[0], {**good[1], "encoding": "not-a-codec"}], False)
        print("EXTERNAL_CORPUS_GATE_CONTRACT_PASS")
if __name__ == "__main__":
    run()
